// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(actor).balance == false || true);
        uint256 prev = c.getBalance(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        assertEq(c.getBalance(actor), prev + amount);
    }
}
